function picture(w,c,originalPicture){
 if(w.art==='pin'&&originalPicture)return originalPicture(w);
 if(['kit348','cap342'].includes(w.art))return soundWordPicture(w)||'<p>'+esc(c.pictureFallback)+'</p>';
 if(!Object.hasOwn(drawings,w.art))return '<p>'+esc(c.pictureFallback)+'</p>';
 return '<svg class="wrt-picture" viewBox="0 0 320 190" role="img" aria-label="'+esc(w.alt)+'"><g stroke="#183430" stroke-width="3" stroke-linejoin="round" stroke-linecap="round">'+drawings[w.art]+'</g></svg>';
}
function connector(w,g){
 const names=g.sounds.map(n=>'Sound '+(n+1)).join(' and ');
 return (g.letters.length===1?'Letter '+w.letters[g.letters[0]]+' goes with ':'Letters '+g.letters.map(n=>w.letters[n]).join(' and ')+' go with ')+names+'.';
}
function model(v,id=v.selected,frame=v.work[id].frame){
 const r=soundTrailReference(v,id,frame),w=r.word,letterX=i=>160+(i-(w.letters.length-1)/2)*54,dotX=i=>160+(i-(w.phonemes.length-1)/2)*60;
 let svg='',splitLinks='';
 for(const g of w.groups){
  const x=g.letters.reduce((n,i)=>n+letterX(i),0)/g.letters.length,active=frame===4||frame>0&&w.groups[frame-1]===g,cls=active?' wrt-linked':'';
  if(g.letters.length>1&&g.letters.some((n,i)=>i>0&&n!==g.letters[i-1]+1)){
   // Separate curved paths cross over the intervening consonant's route, never join it.
   const d=g.letters.map(i=>'M'+letterX(i)+' 63Q'+letterX(i)+' 94 '+dotX(g.sounds[0])+' 117').join('');
   splitLinks+='<path class="wrt-crossing-gap" d="'+d+'"/><path class="wrt-link'+cls+'" d="'+d+'"/>';continue;
  }
  if(g.letters.length>1)svg+='<path class="wrt-link'+cls+'" d="M'+letterX(g.letters[0])+' 65H'+letterX(g.letters.at(-1))+'M'+x+' 65v16"/>';
  else svg+='<path class="wrt-link'+cls+'" d="M'+x+' 63v18"/>';
  for(const n of g.sounds)svg+='<path class="wrt-link'+cls+'" d="M'+x+' 81  '+dotX(n)+' 117"/>';
 }
 svg+=splitLinks;
 for(const[i,l]of w.letters.entries())svg+='<g role="img" aria-label="Letter '+esc(l)+'"><rect class="wrt-print'+(r.letters.includes(i)?' wrt-selected':'')+'" x="'+(letterX(i)-22)+'" y="12" width="44" height="48" rx="4"/><text x="'+letterX(i)+'" y="47" aria-hidden="true" class="wrt-glyph">'+esc(l)+'</text></g>';
 for(let i=0;i<w.phonemes.length;i++)svg+='<g role="img" aria-label="Sound '+(i+1)+'"><circle class="wrt-sound'+(r.sounds.includes(i)?' wrt-selected':'')+'" cx="'+dotX(i)+'" cy="137" r="18"/><text x="'+dotX(i)+'" y="143" class="wrt-number" aria-hidden="true">'+(i+1)+'</text></g>';
 return '<figure class="wrt-model"><figcaption>'+esc(v.source.copy.model)+'</figcaption><svg class="wrt-map" viewBox="0 0 320 170" role="group" aria-label="'+esc(display(w)+': '+v.source.copy.model)+'" aria-describedby="wrt-map-'+id+'"><desc id="wrt-map-'+id+'">'+esc(w.groups.map(g=>connector(w,g)).join(' '))+'</desc>'+svg+'</svg></figure>';
}
function printed(w){return '<div class="wrt-print-only" role="group" aria-label="'+esc(w.label)+'">'+w.letters.map(l=>'<span>'+esc(l)+'</span>').join('')+'</div>';}
export function soundTrailPage(v,originalPicture=null){
 const c=v.source.copy,w=v.source.words[v.selected],a=v.work[v.selected],pair=soundTrailPair(v);
 let task;
 if(v.compare){
  task='<h2 id="wr-task" tabindex="-1">'+esc(pair.title)+'</h2><p>'+esc(pair.text)+'</p><div class="wrt-pair">'+pair.ids.map(id=>'<section><h3>'+esc(display(v.source.words[id]))+'</h3>'+context(v.source.words[id])+model(v,id,Object.hasOwn(pair.highlight,id)?pair.highlight[id]+1:4)+'</section>').join('')+'</div><div class="wrt-actions">'+button('back',c.compareBack)+'</div>';
 }else{
  const figures='<figure class="wrt-prop">'+picture(w,c,originalPicture)+'<figcaption>'+esc(w.meaning)+'</figcaption></figure>';
  let mat;
  if(a.tool==='try'){
   const counters=Array.from({length:a.count},(_,i)=>'<span class="wrt-counter" role="img" aria-label="Counter '+(i+1)+'"><i aria-hidden="true">'+(i+1)+'</i></span>').join('');
   mat='<h3>'+esc(c.own)+'</h3>'+printed(w)+'<p class="wrt-prompt">'+esc(c.newUse[w.id]||c.tryPrompt)+'</p><div class="wrt-counters" role="group" aria-label="'+esc(c.own)+'">'+counters+'</div><p id="wrt-count" tabindex="-1">'+esc(soundTrailCounterLine(a.count))+'</p><div class="wrt-counter-actions">'+button('counter',c.add,1,{disabled:a.count===6})+button('counter',c.take,-1,{disabled:a.count===0})+'</div><div class="wrt-actions">'+button('model',c.show)+'</div>';
  }else mat=model(v)+'<p id="wrt-step" tabindex="-1" class="wrt-prompt">'+esc(w.frames[a.frame])+'</p><div class="wrt-actions">'+button('step',c.prev,-1,{disabled:a.frame===0})+button('step',c.next,1,{disabled:a.frame===4})+button('try',c.try)+'</div>';
  task='<h2 id="wr-task" tabindex="-1">'+esc(display(w))+'</h2>'+context(w)+'<div class="wrt-work">'+figures+'<section class="wrt-mat">'+mat+'</section></div>'+(pair?'<div class="wrt-actions">'+button('compare',c.compare[w.id])+'</div>':'');
 }
 const set=v.source.id==='sentences'?'sentences':v.source.id==='final-e'?'vowels':'sounds';
 const sets='<nav class="wrt-sets" aria-label="Choose word set">'+button('set','x and qu','sounds',{pressed:set==='sounds'})+button('set','A final e','vowels',{pressed:set==='vowels'})+button('set','Words in sentences','sentences',{pressed:set==='sentences'})+'</nav>';
 const note=v.source.note?'<details class="wrt-note'+(set==='sentences'?' wrt-sentence-note':'')+'" data-wrt-note><summary>'+esc(v.source.note.title)+'</summary>'+v.source.note.text.split('\n\n').map(p=>'<p>'+esc(p)+'</p>').join('')+'<p>'+esc(v.source.note.guide)+'</p></details>':'';
 const choices='<nav class="wrt-words" aria-label="Choose a word">'+Object.keys(v.source.words).map(id=>button('word',display(v.source.words[id]),id,{pressed:v.selected===id})).join('')+'</nav>';
 return '<section class="wr-room wrt-room" data-word-room-root data-wrt-root data-wrt-word="'+v.selected+'"><header class="wr-header">'+button('leave',c.back)+'<div><h1>'+esc(c.title)+'</h1></div></header><p class="wrt-opening">'+esc(c.opening)+'</p>'+sets+choices+'<div class="wrt-task">'+task+'</div><p id="wr-status" class="sr-only" role="status" aria-live="polite" aria-atomic="true"></p><p class="wrt-visit">'+esc(c.visit)+'</p>'+note+'<details class="wrt-grownups"><summary>'+esc(c.grownupTitle)+'</summary><p>'+esc(v.source.grownup)+'</p>'+(v.source.extraGrownup?'<p>'+esc(v.source.extraGrownup)+'</p>':'')+(v.source.guide[w.id]?'<p>'+esc(v.source.guide[w.id])+'</p>':'')+'<p>'+esc(w.reference)+'</p></details></section>';
}
